/**
 * test-critic-raw.mjs
 * Isolation test: runs the Critic agent against simple-portfolio
 * and prints the RAW model output BEFORE validation, for diagnosis.
 */

import { readFileSync, existsSync } from 'node:fs';
import { resolve } from 'node:path';

const PORT_DIR = 'regression-output/simple-portfolio';

// Check the portfolio exists
if (!existsSync(PORT_DIR)) {
  console.error('simple-portfolio not found — run the regression test first');
  process.exit(1);
}

// Read the files generated by the pipeline
const forgeDir = resolve(PORT_DIR, '.forge');
const sitemapPath = resolve(forgeDir, 'sitemap.json');

// We need to construct the critic input manually. Read generated files.
const files = {};
const filePaths = [
  'app/layout.tsx',
  'app/page.tsx',
  'app/globals.css',
  'components/Hero.tsx',
  'components/Navbar.tsx',
  'components/Footer.tsx',
  'components/Hero.module.css',
  'components/Navbar.module.css',
  'components/Footer.module.css',
  'app/page.module.css',
  'lib/gsap-config.ts',
  'lib/lenis-provider.tsx',
  'hooks/useReducedMotion.ts',
  'hooks/useLenis.ts',
  'next.config.js',
  'tsconfig.json',
  'package.json',
];

for (const fp of filePaths) {
  const full = resolve(PORT_DIR, fp);
  if (existsSync(full)) {
    files[fp] = readFileSync(full, 'utf-8');
  }
}

const sitemap = existsSync(sitemapPath)
  ? JSON.parse(readFileSync(sitemapPath, 'utf-8'))
  : { pages: [{ path: '/', name: 'Home', sections: [] }] };

// Build the minimal brief, designTokens, motionPlan the critic needs
const brief = {
  name: 'Simple Portfolio',
  description: 'A minimal portfolio landing page with smooth scroll, hero section, and about section.',
  mood: ['minimal', 'clean', 'modern'],
  industry: 'portfolio',
};

const designTokens = {
  colorPalette: { primary: '#0a0a0a', accent: '#6366f1', background: '#ffffff', surface: '#f5f5f5', text: '#0a0a0a' },
  typography: { displayFont: { family: 'Inter', weights: [700, 900] }, textFont: { family: 'Inter', weights: [400, 500] } },
  spacing: { scale: [4, 8, 16, 24, 32, 48, 64, 96] },
  motionPersonality: { description: 'Smooth and intentional' },
};

const motionPlan = {
  globalScrollBehavior: 'smooth',
  animations: [],
};

const criticInput = {
  brief,
  designTokens,
  motionPlan,
  sitemap,
  generatedCode: { files, dependencies: {}, notes: '' },
};

// Directly call the Ollama API to simulate what CriticAgent does
import('ollama').then(({ Ollama }) => {
  const client = new Ollama({ host: 'http://localhost:11434' });

  // Build the same system prompt as CriticAgent
  const systemPrompt = `You are a strict, adversarial design director and technical architect.
You evaluate the generated codebase against the project brief, design tokens, motion plan, and the architecture sitemap.

Your job is NOT to be nice. Your job is to prevent generic, "AI-looking", or broken multi-page implementations from reaching the user.
You evaluate the entire codebase as a holistic system.

EVALUATION CRITERIA:
1. Sitemap Compliance: Are all pages and routes from the sitemap present and correctly structured? Do they share the requested layout (navType, footerType)?
2. Distinguishability: Does it look like a generic Bootstrap/Tailwind template? (If yes, score heavily down). Does it capture the requested mood?
3. Animation Audit: Did they implement the exact motion choreography? Is it janky? Did they use will-change properly?
4. Token Compliance: Did they strictly use the provided typography, colors, and scaling formulas, or did they invent their own?

Output valid JSON matching the CriticReport schema. No markdown, no explanations outside JSON.

The JSON must have EXACTLY these top-level fields:
- "assessments": array of page assessment objects (at minimum 1 entry)
- "overallConfidence": number from 1-10
- "revisionNotes": array of strings
- "antiPatternsDetected": array of strings
- "summary": string paragraph

Each entry in "assessments" must have:
- "pageOrSection": string
- "distinguishability": object with "score" (1-10 number), "notes" (string), "specificChanges" (array of strings)
- "animationAudit": object with "allJustified" (boolean), "unjustifiedAnimations" (array of strings)
- "tokenCompliance": object with "compliant" (boolean), "drifts" (array of strings)`;

  // Format the user message the same way CriticAgent.formatInput does
  let userMessage = `## Project Brief
Name: ${brief.name}
Description: ${brief.description}
Industry: ${brief.industry}
Mood: ${brief.mood.join(', ')}

## Architect Sitemap
${JSON.stringify(sitemap, null, 2)}

## Design Tokens
${JSON.stringify(designTokens, null, 2)}

## Motion Plan (what codegen was supposed to implement)
${JSON.stringify(motionPlan, null, 2)}

## Generated Code (what you're reviewing)
`;

  for (const [fileName, content] of Object.entries(files)) {
    userMessage += `\n### File: ${fileName}\n\`\`\`\n${content}\n\`\`\`\n`;
  }

  userMessage += '\n\nIMPORTANT: Respond with valid JSON only. No markdown fences, no explanation.';

  const messages = [
    { role: 'system', content: systemPrompt },
    { role: 'user', content: userMessage },
  ];

  const totalInputChars = systemPrompt.length + userMessage.length;
  console.log(`\n=== CRITIC ISOLATION TEST ===`);
  console.log(`Input size: ${totalInputChars} chars (~${Math.round(totalInputChars / 4)} tokens est.)`);
  console.log(`Files included: ${Object.keys(files).join(', ')}`);
  console.log(`\nSending to qwen2.5-coder:7b with format:json, num_ctx:8192, num_predict:4096...`);
  console.log('(This may take 1-2 minutes)\n');

  client.chat({
    model: 'qwen2.5-coder:7b',
    messages,
    format: 'json',
    options: {
      num_ctx: 8192,
      num_predict: 4096,
      temperature: 0.1,
      repeat_penalty: 1.05,
    },
  }).then(response => {
    const rawText = response.message.content;
    const usage = {
      inputTokens: response.prompt_eval_count ?? 0,
      outputTokens: response.eval_count ?? 0,
    };

    console.log('=== RAW MODEL OUTPUT (before any validation) ===');
    console.log(rawText);
    console.log('\n=== TOKEN USAGE ===');
    console.log(`Input tokens:  ${usage.inputTokens}`);
    console.log(`Output tokens: ${usage.outputTokens}`);
    console.log(`num_predict limit: 4096`);

    // Try to parse it
    let parsed;
    try {
      parsed = JSON.parse(rawText);
      console.log('\n=== PARSED JSON TOP-LEVEL KEYS ===');
      console.log(Object.keys(parsed));
      console.log('\n=== FIELD PRESENCE CHECK ===');
      console.log(`  assessments:         ${JSON.stringify(parsed.assessments !== undefined)}`);
      console.log(`  overallConfidence:   ${JSON.stringify(parsed.overallConfidence !== undefined)}`);
      console.log(`  summary:             ${JSON.stringify(parsed.summary !== undefined)}`);
      console.log(`  revisionNotes:       ${JSON.stringify(parsed.revisionNotes !== undefined)}`);
      console.log(`  antiPatternsDetected: ${JSON.stringify(parsed.antiPatternsDetected !== undefined)}`);

      if (parsed.assessments) {
        console.log(`  assessments length:  ${parsed.assessments.length}`);
        if (parsed.assessments[0]) {
          console.log(`  assessments[0] keys: ${JSON.stringify(Object.keys(parsed.assessments[0]))}`);
        }
      }
    } catch (e) {
      console.log('\n=== JSON PARSE FAILED ===');
      console.log(`Error: ${e.message}`);
      console.log('First 500 chars of raw text:');
      console.log(rawText.substring(0, 500));
    }

    // Check if truncated (output tokens near limit)
    if (usage.outputTokens >= 3800) {
      console.log('\n⚠️  WARNING: Output tokens near num_predict limit — likely truncated!');
    }
  }).catch(err => {
    console.error('Ollama call failed:', err.message);
  });
}).catch(err => {
  console.error('Failed to import ollama:', err.message);
});
